package com.pvp.travelmatch.service;
import com.fasterxml.jackson.databind.*; import com.pvp.travelmatch.entity.PaymentType; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.net.*; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.util.*;
@Service @RequiredArgsConstructor public class RazorpayPaymentProvider implements PaymentProviderService{
 private final ObjectMapper mapper; private final HttpClient client=HttpClient.newHttpClient(); @Value("${razorpay.key-id:}") private String keyId; @Value("${razorpay.key-secret:}") private String keySecret; @Value("${razorpay.webhook-secret:}") private String webhookSecret; @Value("${razorpay.base-url:https://api.razorpay.com/v1}") private String baseUrl;
 public ProviderOrder createOrder(long amountPaise,String receipt,PaymentType type,Long referenceId){ if(keyId.isBlank()||keySecret.isBlank())throw new IllegalStateException("Razorpay is not configured"); try{Map<String,Object>b=new LinkedHashMap<>();b.put("amount",amountPaise);b.put("currency","INR");b.put("receipt",receipt);Map<String,String> notes=new LinkedHashMap<>(); notes.put("type",type.name()); if(referenceId!=null) notes.put("referenceId",String.valueOf(referenceId)); b.put("notes",notes);String auth=Base64.getEncoder().encodeToString((keyId+":"+keySecret).getBytes(StandardCharsets.UTF_8));HttpRequest r=HttpRequest.newBuilder(URI.create(baseUrl+"/orders")).header("Authorization","Basic "+auth).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(b))).build();HttpResponse<String>x=client.send(r,HttpResponse.BodyHandlers.ofString());if(x.statusCode()/100!=2)throw new IllegalStateException("Unable to create Razorpay order");JsonNode n=mapper.readTree(x.body());return new ProviderOrder(n.get("id").asText(),n.get("amount").asLong(),n.get("currency").asText());}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("Razorpay order creation failed",e);}}
 public boolean verifyPaymentSignature(String orderId,String paymentId,String signature){return hmac(orderId+"|"+paymentId,signature,keySecret);} public boolean verifyWebhookSignature(String payload,String signature){return hmac(payload,signature,webhookSecret);} private boolean hmac(String payload,String supplied,String secret){if(secret==null||secret.isBlank()||supplied==null||supplied.isBlank())return false;try{var m=javax.crypto.Mac.getInstance("HmacSHA256");m.init(new javax.crypto.spec.SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return java.security.MessageDigest.isEqual(m.doFinal(payload.getBytes(StandardCharsets.UTF_8)),HexFormat.of().parseHex(supplied));}catch(Exception e){return false;}}
}
